    public static int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < nums.length; i++) {
            set.add(nums[i]);
        }

        var result = 0;
        var max = 0;
        for (Integer value : set) {
            if (!set.contains(value - 1)) {
                while (set.contains(value++)) {
                    result++;
                }
                if (max < result) {
                    max = result;
                }
                result = 0;
            }
        }

        return max;
    }
